toolCalls.args:
{"command": "cd /tmp/sv-ace91e8e981e411f82a4dd336b465e69 && \
# Try nm/objdump for the two unknown addresses
apt list --installed 2>/dev/null | grep -q binutils && echo "binutils ok" || true
# Use readelf or objdump to find nearest symbol
for addr in 0x2f4b20 0x2f4c84; do
  echo "=== $addr ==="
  # Find nearest function via sorted symbol table
  nm -C libmonosgen-2.0.so.debug 2>/dev/null | awk -v target="$addr" '
    BEGIN { gsub("0x","",target); best=""; bestaddr=0 }
    /^[0-9a-f]+ [tTwW]/ {
      a = strtonum("0x" $1)
      t = strtonum("0x" target)
      if (a <= t && a > bestaddr) { bestaddr=a; best=$3 }
    }
    END { printf "  nearest: %s (at 0x%x, offset +0x%x)\n", best, bestaddr, strtonum("0x"target)-bestaddr }
  '
done", "description": "Resolve unknown symbols via nm"}

