toolCalls.args:
{"command": "cd /tmp/sv-ace91e8e981e411f82a4dd336b465e69 && \
# Use the symtab with function types only
readelf -s libmonosgen-2.0.so.debug 2>/dev/null | awk '
  $4 == "FUNC" {
    addr = strtonum("0x" $2)
    size = strtonum($3)
    name = $8
    if (addr <= 0x2f4b20 && addr + size > 0x2f4b20) print "0x2f4b20 -> " name " (at 0x" $2 ", size " $3 ")"
    if (addr <= 0x2f4c84 && addr + size > 0x2f4c84) print "0x2f4c84 -> " name " (at 0x" $2 ", size " $3 ")"
  }'", "description": "Find functions by address range in symtab"}

