# Find the nearest FUNC symbol below the addresses
readelf -s libmonosgen-2.0.so.debug 2>/dev/null | awk '
  $4 == "FUNC" && $2 != "00000000" {
    addr = strtonum("0x" $2)
    name = $8
    if (addr <= 0x2f4b20) { d1 = 0x2f4b20 - addr; if (d1 < best1 || best1 == -1) { best1 = d1; n1 = name; a1 = addr } }
    if (addr <= 0x2f4c84) { d2 = 0x2f4c84 - addr; if (d2 < best2 || best2 == -1) { best2 = d2; n2 = name; a2 = addr } }
  }
  BEGIN { best1 = -1; best2 = -1 }
  END {
    printf "0x2f4b20 -> %s (at 0x%x, offset +0x%x)\n", n1, a1, best1
    printf "0x2f4c84 -> %s (at 0x%x, offset +0x%x)\n", n2, a2, best2
